from jsonb_to_recordset($json$[{"id":"che-pe-101","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Dobereiner arranged chemically similar elements into sets of three that he called","options":["octaves","triads","periods","blocks"],"answer_index":1,"explanation":"Each Dobereiner triad contains three related elements, with the middle one intermediate in properties.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-102","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"In a Dobereiner triad the atomic mass of the middle element is approximately","options":["the product of the other two atomic masses","the arithmetic mean of the other two atomic masses","twice the atomic mass of the lightest member","equal to the atomic number of the heaviest member"],"answer_index":1,"explanation":"The middle atomic mass is close to the average of the first and third members.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-103","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Newlands noticed that every eighth element resembled the first and named this regularity the","options":["law of octaves","law of triads","modern periodic law","octet rule of Lewis"],"answer_index":0,"explanation":"He compared the repeating chemical likeness to the octaves of a musical scale.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-104","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Newlands' arrangement gave a useful resemblance of properties only as far as the element","options":["helium","calcium","iron","iodine"],"answer_index":1,"explanation":"Beyond calcium the octave pattern broke down as many new elements were fitted in.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-105","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Mendeleev's periodic law stated that the properties of elements are a periodic function of their","options":["atomic numbers","atomic masses","mass numbers only","neutron counts"],"answer_index":1,"explanation":"Mendeleev ordered the then-known elements by increasing atomic mass and found a repeating pattern.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-106","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"A distinctive feature of Mendeleev's table was that he","options":["placed isotopes in separate groups","left vacant places for elements still undiscovered","arranged elements strictly by atomic number","refused to predict any new element"],"answer_index":1,"explanation":"Gaps such as those for eka-aluminium and eka-silicon were later filled by gallium and germanium.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-107","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"A recognised limitation of Mendeleev's classification is the uncertain position of","options":["alkali metals","isotopes of the same element","halogens","alkaline earth metals"],"answer_index":1,"explanation":"Isotopes have different atomic masses but identical chemistry, so a mass-based table cannot place them uniquely.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-108","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The element Mendeleev called eka-aluminium was later isolated and named","options":["scandium","gallium","germanium","silicon"],"answer_index":1,"explanation":"Eka-aluminium occupies the place under aluminium and matches gallium in properties and atomic mass.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-109","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Eka-silicon of Mendeleev's table corresponds to the later-discovered element","options":["tin","lead","germanium","carbon"],"answer_index":2,"explanation":"Germanium fills the gap Mendeleev left beneath silicon and agrees with his predicted properties.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-110","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Tellurium was placed before iodine in Mendeleev's table even though Te has the greater atomic mass so that","options":["tellurium would sit with the noble gases","chemically similar elements remained in the same group","iodine would have a lower atomic number","the table would contain only eight periods"],"answer_index":1,"explanation":"Chemical analogy (Te with O, S, Se; I with F, Cl, Br) was given priority over a strict mass sequence.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
